/* DayPay v24.2 — embedded payslip fonts (Inter subset, 648 glyphs each).
   jsPDF's built-in helvetica has no ₦ (U+20A6), which produced the old
   payslip's malformed amounts ("116,000", "$16,000", ...). These static
   Inter instances (Regular 400 + Bold 700, subset to the payslip charset:
   ASCII + Latin-1/Extended + ₦ × · — – © quotes) render every glyph.
   Generated from Inter variable (google/fonts) via fonttools instancer +
   subsetter. ~44KB per weight. */
const INTER_REGULAR_B64 = ''
const INTER_BOLD_B64 = ''

/* Register on a jsPDF doc (idempotent per doc — safe to call every time). */
export function registerPayslipFonts(doc) {
  doc.addFileToVFS('DayPay-Inter-Regular.ttf', INTER_REGULAR_B64)
  doc.addFont('DayPay-Inter-Regular.ttf', 'DayPayInter', 'normal')
  doc.addFileToVFS('DayPay-Inter-Bold.ttf', INTER_BOLD_B64)
  doc.addFont('DayPay-Inter-Bold.ttf', 'DayPayInter', 'bold')
}
